CREATE TABLE profiles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,handle TEXT UNIQUE COLLATE NOCASE,display_name TEXT NOT NULL DEFAULT '',bio TEXT NOT NULL DEFAULT '',avatar_key TEXT,privacy TEXT NOT NULL DEFAULT '{}',home_gym TEXT,age16 INTEGER NOT NULL DEFAULT 0,suspended INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE friendships(a TEXT NOT NULL,b TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created INTEGER NOT NULL,PRIMARY KEY(a,b),CHECK(a<>b));
CREATE INDEX friendships_b ON friendships(b,status);
CREATE UNIQUE INDEX friendships_pair ON friendships(MIN(a,b),MAX(a,b));
CREATE TABLE blocks(a TEXT NOT NULL,b TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(a,b));
CREATE INDEX blocks_b ON blocks(b,a);
CREATE TABLE reports(id TEXT PRIMARY KEY,reporter TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,reason TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'open',created INTEGER NOT NULL);
CREATE INDEX reports_status ON reports(status,created);
CREATE TABLE conversations(id TEXT PRIMARY KEY,title TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE TABLE conversation_members(conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,user_id TEXT NOT NULL,muted INTEGER NOT NULL DEFAULT 0,read_at INTEGER NOT NULL DEFAULT 0,receipts INTEGER NOT NULL DEFAULT 1,invited INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(conversation_id,user_id));
CREATE INDEX members_user ON conversation_members(user_id,conversation_id);
CREATE TABLE messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,sender TEXT NOT NULL,body TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'text',media_key TEXT,expires INTEGER,created INTEGER NOT NULL,deleted INTEGER NOT NULL DEFAULT 0,reply_to TEXT);
CREATE INDEX messages_conversation ON messages(conversation_id,created);
CREATE INDEX messages_retention ON messages(created);
CREATE INDEX messages_expiry ON messages(expires);
CREATE INDEX messages_sender ON messages(sender,created);
CREATE TABLE gyms(id TEXT PRIMARY KEY,osm_id TEXT UNIQUE,name TEXT NOT NULL,lat REAL NOT NULL,lng REAL NOT NULL,status TEXT NOT NULL DEFAULT 'pending',source TEXT NOT NULL,updated INTEGER NOT NULL);
CREATE INDEX gyms_area ON gyms(status,lat,lng);
CREATE TABLE checkins(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,gym_id TEXT NOT NULL REFERENCES gyms(id),created INTEGER NOT NULL,visibility TEXT NOT NULL,workout_date TEXT);
CREATE INDEX checkins_user_gym ON checkins(user_id,gym_id,created);
CREATE INDEX checkins_gym ON checkins(gym_id,created);
CREATE TABLE feed_items(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,kind TEXT NOT NULL,body TEXT NOT NULL,visibility TEXT NOT NULL DEFAULT 'friends',created INTEGER NOT NULL);
CREATE INDEX feed_user ON feed_items(user_id,created);
CREATE TABLE reactions(target_id TEXT NOT NULL,user_id TEXT NOT NULL,emoji TEXT NOT NULL,PRIMARY KEY(target_id,user_id));
CREATE TABLE feed_comments(id TEXT PRIMARY KEY,target_id TEXT NOT NULL,user_id TEXT NOT NULL,body TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX comments_target ON feed_comments(target_id,created);
CREATE TABLE friend_mutes(user_id TEXT NOT NULL,friend_id TEXT NOT NULL,PRIMARY KEY(user_id,friend_id));
CREATE TABLE social_invites(code TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE admin_audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,detail TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX audit_created ON admin_audit(created);
CREATE TABLE announcements(id TEXT PRIMARY KEY,body TEXT NOT NULL,start INTEGER NOT NULL,end INTEGER NOT NULL,language TEXT NOT NULL DEFAULT 'all');
CREATE TABLE gym_areas(area TEXT PRIMARY KEY,updated INTEGER NOT NULL);
CREATE TABLE friend_duels(id TEXT PRIMARY KEY,a TEXT NOT NULL,b TEXT NOT NULL,metric TEXT NOT NULL,days INTEGER NOT NULL,start TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created INTEGER NOT NULL,CHECK(a<>b));
CREATE INDEX duels_a ON friend_duels(a,status);
CREATE INDEX duels_b ON friend_duels(b,status);
CREATE TABLE buddies(user_id TEXT PRIMARY KEY,buddy_id TEXT NOT NULL,approved INTEGER NOT NULL DEFAULT 0,last_nudge TEXT,CHECK(user_id<>buddy_id));
CREATE INDEX buddy_recipient ON buddies(buddy_id,approved);
CREATE TABLE shared_sessions(conversation_id TEXT PRIMARY KEY,workout TEXT NOT NULL,rest_until INTEGER NOT NULL DEFAULT 0,created INTEGER NOT NULL);
CREATE TABLE shared_results(conversation_id TEXT NOT NULL,user_id TEXT NOT NULL,minutes REAL NOT NULL,reps INTEGER NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(conversation_id,user_id));
CREATE INDEX comments_user_rate ON feed_comments(user_id,created);
CREATE TABLE content_overrides(kind TEXT NOT NULL,id TEXT NOT NULL,json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',updated INTEGER NOT NULL,PRIMARY KEY(kind,id));
CREATE INDEX content_status ON content_overrides(kind,status);
